#!/usr/bin/env node
/**
 * Makes the sounds of the Android app match the one list of sounds (functions/src/models/shared/sounds.ts):
 * writes android/app/src/main/java/io/sevenfriends/app/SoundIds.java (generated, do not edit) and checks that every jingle
 * has its file android/app/src/main/res/raw/<androidKey>.mp3 (the channel plays it by that name).
 *
 *   npm run sync:android-sounds        (also `npm run check:android-sounds`: fails when the Java file is out of date)
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const source = fs.readFileSync(path.join(root, "functions/src/models/shared/sounds.ts"), "utf8");
const target = path.join(root, "android/app/src/main/java/io/sevenfriends/app/SoundIds.java");
const raw = path.join(root, "android/app/src/main/res/raw");

const sounds = [...source.matchAll(/\{ id: "([^"]+)", kind: "(\w+)", androidKey: "(\w+)", label: "([^"]+)" \}/g)].map((m) => ({ id: m[1], kind: m[2], key: m[3], label: m[4] }));
if (!sounds.length) throw new Error("no sounds found in sounds.ts");
const jingles = sounds.filter((s) => s.kind === "jingle");
const missing = jingles.filter((s) => !fs.existsSync(path.join(raw, `${s.key}.mp3`)));
if (missing.length) throw new Error(`no file res/raw/<key>.mp3 for: ${missing.map((s) => s.key).join(", ")}`);

const list = (values) => values.map((v) => `"${v}"`).join(", ");
const text = `package io.sevenfriends.app;

/** GENERATED by scripts/sync-android-sounds.mjs from functions/src/models/shared/sounds.ts: do not edit. */
final class SoundIds {
    private SoundIds() {}

    /** the keys of the jingles (res/raw/<key>.mp3, the end of the channel name), their saved ids and their names */
    static final String[] JINGLES = {${list(jingles.map((s) => s.key))}};
    static final String[] JINGLE_IDS = {${list(jingles.map((s) => s.id))}};
    static final String[] JINGLE_NAMES = {${list(jingles.map((s) => s.label))}};

    /** The channel key of a saved choice: "silent", a jingle key, or "default" (the phone's own sound) for anything else. */
    static String keyOf(String choice) {
        if ("none".equals(choice)) return "silent";
        for (int i = 0; i < JINGLE_IDS.length; i++) {
            if (JINGLE_IDS[i].equals(choice)) return JINGLES[i];
        }
        // a choice saved under an older file name still finds its jingle by the name in it (as androidKeyOf in sounds.ts)
        if (choice != null && choice.startsWith("file:")) {
            String plain = choice.toLowerCase().replaceAll("[^a-z]", "");
            for (String jingle : JINGLES) {
                if (plain.contains(jingle)) return jingle;
            }
        }
        return "default";
    }
}
`;
if (process.argv.includes("--check")) {
  if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== text) {
    console.error("SoundIds.java is out of date: run npm run sync:android-sounds");
    process.exit(1);
  }
} else {
  if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== text) fs.writeFileSync(target, text);
  console.log(`android sounds: ${jingles.length} jingle(s) -> SoundIds.java`);
}
